import re

def parse_duration(text):
    text = text.strip()
    parts = re.findall(r'([0-9]+)([hms])', text)
    if not parts or ''.join(n + u for n, u in parts) != text or len({u for _, u in parts}) != len(parts):
        raise ValueError('invalid duration')
    return sum(int(n) * {'h': 3600, 'm': 60, 's': 1}[u] for n, u in parts)

